def remove(self, name):
    """Remove a node and all dependencies related to it from the sorter."""
    self.names = [node for node in self.names if node != name]
    self.name2val.pop(name, None)

    dependent_after = self.name2after.pop(name, ())
    for node in dependent_after:
        self.req_after.discard(name)
        self.order = [
            edge for edge in self.order if edge != (node, name)
        ]

    dependent_before = self.name2before.pop(name, ())
    for node in dependent_before:
        self.req_before.discard(name)
        self.order = [
            edge for edge in self.order if edge != (name, node)
        ]

def l33t_match(password, _ranked_dictionaries=RANKED_DICTIONARIES,
               _l33t_table=L33T_TABLE):
    """
    Find l33t matches and include detailed information about each match.

    Single-character matches are excluded.
    """
    matches = []

    subtable = relevant_l33t_subtable(password, _l33t_table)
    if not subtable:
        return matches

    for substitution_map in enumerate_l33t_subs(subtable):
        translated_password = translate(password, substitution_map)

        dictionary_matches = dictionary_match(
            translated_password,
            _ranked_dictionaries=_ranked_dictionaries,
        )

        for dictionary_match_result in dictionary_matches:
            i = dictionary_match_result['i']
            j = dictionary_match_result['j']

            # Exclude matches where the token is only one character long.
            if j - i + 1 <= 1:
                continue

            original_token = password[i:j + 1]
            translated_token = translated_password[i:j + 1]

            # Require at least one actual l33t substitution in the match.
            if not any(
                original_char != translated_char
                for original_char, translated_char
                in zip(original_token, translated_token)
            ):
                continue

            # Keep only substitutions that occur in this matched token.
            used_substitutions = {
                l33t_char: translated_char
                for l33t_char, translated_char in substitution_map.items()
                if l33t_char in original_token
            }

            detailed_substitutions = [
                {
                    'original': l33t_char,
                    'translated': translated_char,
                }
                for l33t_char, translated_char
                in used_substitutions.items()
            ]

            match = dictionary_match_result.copy()
            match.update({
                'token': original_token,
                'original_token': original_token,
                'position': {
                    'start': i,
                    'end': j,
                },
                'sub': used_substitutions,
                'l33t_substitutions': detailed_substitutions,
                'l33t': True,
            })

            matches.append(match)

    return sorted(matches, key=lambda match: (match['i'], match['j']))

