                in zip(original_token, translated_token)
            ):
                continue

            # Keep only substitutions used in the matched token.
            used_substitutions = {
                l33t_char: translated_char
                for l33t_char, translated_char in substitution_map.items()
                if l33t_char in original_token
            }

            detailed_substitutions = [
                {
                    'original': l33t_char,
                    'translated': translated_char,
                }
                for l33t_char, translated_char
                in used_substitutions.items()
            ]

            match = dictionary_match_result.copy()
            match.update({
                'token': original_token,
                'original_token': original_token,
                'position': {
                    'start': i,
                    'end': j,
                },
                'sub': used_substitutions,
                'l33t_substitutions': detailed_substitutions,
                'l33t': True,
            })

            matches.append(match)

    # Sort by the matched substring's start position, then end position.
    return sorted(matches, key=lambda match: (match['i'], match['j']))
